-- SELECT t.New_ClickId, m.ClickId,*
UPDATE m SET m.ClickId = t.New_ClickId
FROM dbo.MemberInfo m WITH (ROWLOCK, UPDLOCK)
	INNER JOIN #TempClickStatistics t on m.CustId = t.CustId AND m.AffId = t.AffId
WHERE m.ClickId <> t.New_ClickId